We start by proving the following 2 auxiliary statements:

\begin{claim} \label{clm:proj_abc}
    For each point $v\in \TS(D)$, 
    \begin{itemize}
            \item $(c,f(v))_{\TS}=(c,p(v))_{\TS}$;
            \item $(b,f(v))_{\TS} - (d,f(v))_{\TS} = (b,p(v))_{\TS} - (d,p(v))_{\TS}$. 
    \end{itemize}
\end{claim}
\begin{proof}
    If $f(v)\in \TS(D')$, then $f(v)=p(v)$ and the inequalities clearly hold. Otherwise, $f(v)$ lies in the $3$-dimensional set (the triangular prism). We denote by $(x,y,z)$ the associated vector of $f(v)$. By \Cref{obs:terminal}, $(c,f(v))_{\TS} = x+y+z$. From \Cref{obs: proj_ down}, $p(v) = f(v) + (z/2)\cdot(w_2-w_1) = (x,y+z,0)$, so $(c,p(v))_\TS = x+y+z = (c,f(v))_\TS$. 
From \Cref{obs:terminal}, $(d,f(v))_\TS = 2-x+z$ and $(b,f(v))_\TS = 1+x+z$, so $(b,f(v))_\TS - (d,f(v))_\TS = 2x-1$, which equals $(b,p(v))_\TS-(d,p(v))_\TS$ as the associated vectors of $f(v)$ and $p(v)$ have the same $x$ coordinates (from \Cref{obs: proj_ down}).
\end{proof}

\begin{claim} \label{clm:x}
    For every vertex $v\in V(G)$, 
    \begin{itemize}
        \item $\ell_1(v,d)+\ell_1(v,b) \ge 2\card{f(v)[x]-f(v+w_1)[x]}$; 
        \item $\ell'_2(v,d)+\ell'_2(v,b) \ge 2\card{f(v)[x]-f(v+w_2)[x]}$;
        \item $(a,f(v))_{\TS}+(b,f(v))_\TS \ge 2 + 2\big(f(v)[x]\big)^+$; 
        \item $(d,f(v))_\TS+(e,f(v))_\TS \ge 2 + 2\big(1-f(v)[x]\big)^+$. 
    \end{itemize}
\end{claim}
\begin{proof}
Let $(x,y,z)$ be the associated vector of $f(v)$ and let $(x_1,y_1,z_1)$ be that of $f(v+w_1)$. 
From \Cref{obs: dist in TS}, $(f(v),f(v+w_1))_\TS \ge \card{x-x_1}+\card{z-z_1}$. From \Cref{obs:terminal}, $(f(v),b)_\TS+(f(v),d)_\TS=3+2z$ and $(f(v+w_1),b)_\TS+(f(v+w_1),d)_\TS=3+2z_1$. Therefore,
\[
  \begin{split}
        \ell_1(v,d)+\ell_1(v,b) & = \bigg((f(v),f(v+w_1))_\TS+(d,f(v))_\TS-(d,f(v+w_1))_\TS\bigg)\\
      & \quad\quad  +
\bigg((f(v),f(v+w_1))_\TS+(b,f(v))_\TS-(b,f(v+w_1))_\TS\bigg) \\ 
        & \ge 2\card{x-x_1} + 2\card{z-z_1} + 3 + 2z - 3 - 2z_1 \ge 2\card{x-x_1}.
  \end{split}
\]
The second inequality can be proved similarly.
For the third inequality, by \Cref{obs:terminal}, we get that $(a,f(v))_\TS+(b,f(v))_\TS = 2 + x + \card{x} = 2 + 2\max\{x,0\}$, and the last one can be proved similarly.
\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof}
We will show that
\[\vol(\fset,\delta)-\opt\ge \sum_v (2\ell_x(v)+2\ell_y(v)+2\ell^1_z(v)) + \sum_{v:v[x]=0} 2\big(p(v)[x]\big)^+ + \sum_{v:v[x]=1} 2\big(1-p(v)[x]\big)^+.\]
Note that this (together with \Cref{clm:transfer}) immediately implies the lemma.

From \Cref{obs: proj_ down}, the associated vectors for $p(v)$ and $f(v)$ have the same $x$ coordinates. Therefore, we can replace all $f(v)$ by $p(v)$ in the of \Cref{clm:x}, obtaining 
    \begin{itemize}
        \item $\sum_{i,j} \ell(\mathsf{ab}[i,j]) = \sum_{v:v[x]=0} 2\big(p(v)[x]\big)^+$;
        \item $\sum_{i,j} \ell(\mathsf{de}[i,j]) = \sum_{v:v[x]=1} 2\big(1-p(v)[x]\big)^+$;
        \item $\ell_1(v,d)+\ell_1(v,b) \ge 2\card{p(v)[x]-p(v+w_1)[x]}$;
        \item $\ell'_2(v,d)+\ell'_2(v,b) \ge 2\card{p(v)[x]-p(v+w_2)[x]}$.
    \end{itemize} 
    As $w_1+w_2=w_3+w_4$, from the third and the fourth inequalities above,
    \[
        \sum_v (\ell_1(v,d)+\ell_1(v,b) + \ell'_2(v,d)+\ell'_2(v,b)) \ge \sum_v 2\card{p(v)[x]-p(v+w_1+w_2)[x]} = \sum_v \ell_y(v)\]
    For any $v$, we define the associated vectors as $p(v)=(x,y,0)$, $p(v+w_3) = (x_3,y_3,0)$ and $p(v+w_4) = (x_4,y_4,0)$. From \Cref{obs: dist in TS}, $2(p(v),p(v+w_3))_{\TS} = \card{(2x+y)-(2x_3+y_3)} + \card{y-y_3}$. Thus by \Cref{clm:proj_abc}, \Cref{obs:terminal} and the property that $(f(v),f(v+w_3))_{\TS} \ge (p(v),p(v+w_3))_{\TS}$, 
    \begin{align*}
            \ell'_3(v,d)+\ell_3(v,b)+2\ell_3(v,c) 
        & =   4(f(v),f(v+w_3))_\TS - (f(v),d)_\TS + (f(v),b)_\TS + 2(f(v),c)_\TS \\
            & \quad\quad + (f(v+w_3),d)_\TS - (f(v+w_3),b)_\TS - 2 (f(v+w_3),c)_\TS \\
       & \ge  4(p(v),p(v+w_3))_\TS - (p(v),d)_\TS + (p(v),b)_\TS + 2(p(v),c)_\TS \\
            & \quad\quad + (p(v+w_3),d)_\TS - (p(v+w_3),b)_\TS - 2 (p(v+w_3),c)_\TS \\
        & \ge  2(\card{(2x+y)-(2x_3+y_3)} + \card{y-y_3}) - (2-x) + x + 1 + 2x + 2y \\
            & \quad\quad + (2-x_3) -x_3 - 1 - 2x_3 -2y_3 \\
        & =    2\card{y-y_3} + 2(\card{(2x+y)-(2x_3+y_3)} - ((2x+y)-(2x_3+y_3))) \\
        & \ge  2\card{y-y_3} + 4\bigg(2(x-x_3)+(y-y_3)\bigg)^+ = 2\ell_x(v).
    \end{align*}
    Similarly, we can also show that $\ell_4(v,d)+\ell'_4(v,b)+2\ell_4(v,c) \ge 2\ell_z^1(v)$. The lemma now follows from \Cref{lem:cost} and the fact that $\vol(\fset,\delta)-\opt=\sum_{P\in \pset}\ell(P)$. 
\end{proof}
